<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Personal Expense Tracker</title>
  <style>
    :root {
      color-scheme: light;
      font-family: Arial, sans-serif;
      background: #f4f6f8;
      color: #20252b;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      padding: 24px;
    }

    main {
      max-width: 900px;
      margin: 0 auto;
    }

    h1, h2 { margin-top: 0; }

    section {
      background: #fff;
      border: 1px solid #dce1e6;
      border-radius: 8px;
      padding: 20px;
      margin-bottom: 18px;
    }

    form, .filters {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
      gap: 14px;
      align-items: end;
    }

    label {
      display: flex;
      flex-direction: column;
      gap: 6px;
      font-weight: 600;
      font-size: 0.9rem;
    }

    input, select, button {
      font: inherit;
      min-height: 40px;
      border: 1px solid #bcc5ce;
      border-radius: 5px;
      padding: 8px 10px;
    }

    button {
      cursor: pointer;
      background: #1769aa;
      color: white;
      border-color: #1769aa;
      font-weight: 600;
    }

    button:hover { background: #12558b; }

    .error {
      color: #b42318;
      min-height: 1.3em;
      margin: 12px 0 0;
    }

    .summary {
      display: flex;
      flex-wrap: wrap;
      gap: 20px;
      align-items: center;
    }

    .total {
      font-size: 1.3rem;
      font-weight: 700;
    }

    .category-summary {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
      gap: 10px;
      width: 100%;
    }

    .cat-total {
      background: #eef3f7;
      border-radius: 5px;
      padding: 10px;
    }

    .expense-list {
      display: grid;
      gap: 10px;
    }

    .expense {
      display: grid;
      grid-template-columns: 1fr 1fr 1fr auto;
      gap: 12px;
      align-items: center;
      border: 1px solid #e0e5e9;
      border-radius: 6px;
      padding: 12px;
    }

    .expense-info {
      display: flex;
      flex-direction: column;
      gap: 3px;
    }

    .expense-amount { font-weight: 700; }

    .expense-note {
      color: #5c6670;
      font-size: 0.9rem;
    }

    .exp-del {
      background: #b42318;
      border-color: #b42318;
    }

    .exp-del:hover { background: #8f1c14; }

    .empty {
      color: #66727d;
      text-align: center;
      padding: 18px;
    }

    @media (max-width: 600px) {
      .expense {
        grid-template-columns: 1fr 1fr;
      }

      .expense button {
        grid-column: span 2;
      }
    }
  </style>
</head>
<body>
  <main>
    <h1>Personal Expense Tracker</h1>

    <section>
      <h2>Add Expense</h2>
      <form id="expense-form">
        <label>
          Amount
          <input id="amount" type="number" step="0.01" min="0.01" required>
        </label>

        <label>
          Category
          <select id="category">
            <option value="groceries">Groceries</option>
            <option value="transport">Transport</option>
            <option value="bills">Bills</option>
            <option value="fun">Fun</option>
          </select>
        </label>

        <label>
          Date
          <input id="date" type="date" required>
        </label>

        <label>
          Note
          <input id="note" type="text" maxlength="200">
        </label>

        <button id="add-expense" type="submit">Add Expense</button>
      </form>
      <p id="form-error" class="error" role="alert"></p>
    </section>

    <section>
      <h2>Filters</h2>
      <div class="filters">
        <label>
          Category
          <select id="filter-category">
            <option value="all">All categories</option>
            <option value="groceries">Groceries</option>
            <option value="transport">Transport</option>
            <option value="bills">Bills</option>
            <option value="fun">Fun</option>
          </select>
        </label>

        <label>
          From
          <input id="filter-from" type="date">
        </label>

        <label>
          To
          <input id="filter-to" type="date">
        </label>
      </div>
    </section>

    <section>
      <div class="summary">
        <div class="total">Visible total: $<span id="total">0.00</span></div>
        <div id="category-summary" class="category-summary"></div>
      </div>
    </section>

    <section>
      <h2>Expenses</h2>
      <div id="expense-list" class="expense-list"></div>
    </section>
  </main>

  <script>
    (function () {
      const storageKey = "personal-expenses";
      const categories = ["groceries", "transport", "bills", "fun"];
      let expenses = loadExpenses();

      const form = document.getElementById("expense-form");
      const amountInput = document.getElementById("amount");
      const categoryInput = document.getElementById("category");
      const dateInput = document.getElementById("date");
      const noteInput = document.getElementById("note");
      const error = document.getElementById("form-error");
      const list = document.getElementById("expense-list");
      const total = document.getElementById("total");
      const categorySummary = document.getElementById("category-summary");
      const filterCategory = document.getElementById("filter-category");
      const filterFrom = document.getElementById("filter-from");
      const filterTo = document.getElementById("filter-to");

      function loadExpenses() {
        try {
          const saved = JSON.parse(localStorage.getItem(storageKey));
          return Array.isArray(saved) ? saved : [];
        } catch (e) {
          return [];
        }
      }

      function saveExpenses() {
        localStorage.setItem(storageKey, JSON.stringify(expenses));
      }

      function money(value) {
        return Number(value).toFixed(2);
      }

      function getVisibleExpenses() {
        const category = filterCategory.value;
        const from = filterFrom.value;
        const to = filterTo.value;

        return expenses.filter(function (expense) {
          return (category === "all" || expense.category === category) &&
            (!from || expense.date >= from) &&
            (!to || expense.date <= to);
        });
      }

      function render() {
        const visible = getVisibleExpenses();
        list.innerHTML = "";

        const ordered = visible.slice().sort(function (a, b) {
          return (b.createdAt || 0) - (a.createdAt || 0);
        });

        if (ordered.length === 0) {
          const empty = document.createElement("div");
          empty.className = "empty";
          empty.textContent = "No expenses match the current filters.";
          list.appendChild(empty);
        } else {
          ordered.forEach(function (expense) {
            const row = document.createElement("div");
            row.className = "expense";
            row.dataset.id = expense.id;

            const amount = document.createElement("div");
            amount.className = "expense-info expense-amount";
            amount.textContent = "$" + money(expense.amount);

            const category = document.createElement("div");
            category.className = "expense-info";
            category.textContent = expense.category;

            const date = document.createElement("div");
            date.className = "expense-info";
            date.textContent = expense.date;

            if (expense.note) {
              const note = document.createElement("span");
              note.className = "expense-note";
              note.textContent = expense.note;
              category.appendChild(note);
            }

            const del = document.createElement("button");
            del.type = "button";
            del.className = "exp-del";
            del.textContent = "Delete";
            del.addEventListener("click", function () {
              expenses = expenses.filter(function (item) {
                return item.id !== expense.id;
              });
              saveExpenses();
              render();
            });

            row.append(amount, category, date, del);
            list.appendChild(row);
          });
        }

        total.textContent = money(visible.reduce(function (sum, expense) {
          return sum + Number(expense.amount);
        }, 0));

        categorySummary.innerHTML = "";
        categories.forEach(function (category) {
          const categoryTotal = visible
            .filter(function (expense) { return expense.category === category; })
            .reduce(function (sum, expense) { return sum + Number(expense.amount); }, 0);

          const item = document.createElement("div");
          item.className = "cat-total";
          item.dataset.cat = category;
          item.textContent = category + ": $" + money(categoryTotal);
          categorySummary.appendChild(item);
        });
      }

      form.addEventListener("submit", function (event) {
        event.preventDefault();
        const amount = Number(amountInput.value);

        if (!Number.isFinite(amount) || amount <= 0 || !dateInput.value) {
          error.textContent = "Enter a valid positive amount and a date.";
          return;
        }

        error.textContent = "";
        expenses.push({
          id: String(Date.now()) + Math.random().toString(16).slice(2),
          amount: amount,
          category: categoryInput.value,
          date: dateInput.value,
          note: noteInput.value.trim(),
          createdAt: Date.now()
        });
        saveExpenses();
        amountInput.value = "";
        render();
      });

      [filterCategory, filterFrom, filterTo].forEach(function (control) {
        control.addEventListener("change", render);
      });

      render();
    })();
  </script>
</body>
</html>
